const upsertFinanceOffer = `-- name: UpsertFinanceOffer :one

INSERT INTO finance_offers (id, account_id, listing_id, product_type, partner_ref, external_offer_ref, status, disclosure, consent_id, expires_at,
    created_at, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, 'OFFERED', $7, $8, $9, $10, $10)
ON CONFLICT (partner_ref, external_offer_ref) DO UPDATE SET disclosure = EXCLUDED.disclosure, expires_at = EXCLUDED.expires_at,
    consent_id = EXCLUDED.consent_id, updated_at = EXCLUDED.updated_at
 WHERE finance_offers.status = 'OFFERED' AND finance_offers.account_id = EXCLUDED.account_id
RETURNING id, account_id, listing_id, product_type, partner_ref, external_offer_ref, status, owner_payout_preference, disclosure, consent_id, expires_at, decided_at, created_at, updated_at
`

type UpsertFinanceOfferParams struct {
	ID               ids.ID
	AccountID        ids.ID
	ListingID        *ids.ID
	ProductType      string
	PartnerRef       string
	ExternalOfferRef string
	Disclosure       []byte
	ConsentID        ids.ID
	ExpiresAt        *time.Time
	CreatedAt        time.Time
}

// 28–30 Financing, insurance and smart access --------------------------------
func (q *Queries) UpsertFinanceOffer(ctx context.Context, db DBTX, arg UpsertFinanceOfferParams) (FinanceOffer, error) {
	row := db.QueryRow(ctx, upsertFinanceOffer,
		arg.ID,
		arg.AccountID,
		arg.ListingID,
		arg.ProductType,
		arg.PartnerRef,
		arg.ExternalOfferRef,
		arg.Disclosure,
		arg.ConsentID,
		arg.ExpiresAt,
		arg.CreatedAt,
	)
	var i FinanceOffer
	err := row.Scan(
		&i.ID,
		&i.AccountID,
		&i.ListingID,
		&i.ProductType,
		&i.PartnerRef,
		&i.ExternalOfferRef,
		&i.Status,
		&i.OwnerPayoutPreference,
		&i.Disclosure,
		&i.ConsentID,
		&i.ExpiresAt,
		&i.DecidedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
